/**
 * Operations index — was auto-generated by generate-node.ts, now MANUALLY PATCHED.
 *
 * DO NOT REGENERATE this file without first fixing the generator. The previous
 * generator hardcoded `additionalOptions.` as the prefix for every queryParam,
 * but most property descriptions declare params at top-level (and Loki uses
 * `logQuery`, getSeries uses `match`). Regenerating with the old generator
 * silently reintroduces the empty-query bug that broke all Prometheus/Loki
 * demos at v0.1.1.
 *
 * Uses n8n built-in this.helpers.request() — no axios dependency.
 */
import { IDataObject, IExecuteFunctions, NodeOperationError } from "n8n-workflow";
import { RetryingRequest } from "../../../helpers/requestExecution";

type InputData = IDataObject | IDataObject[];

type OperationContext = {
  auth: RetryingRequest;
  baseUrl: string;
  ctx: IExecuteFunctions;
  getParam: <T = string>(name: string, defaultValue?: T) => T;
  headers: Record<string, string>;
  inputData: InputData;
  itemIndex: number;
};

type OperationHandler = (context: OperationContext) => Promise<unknown>;
type ResourceHandlers = Record<string, OperationHandler>;

/** Which `type: json` field a value came from — named in the error on invalid JSON. */
type JsonField = { ctx: IExecuteFunctions; itemIndex: number; display: string; name: string };

const UNSET = Symbol("unset");

/**
 * ⛔ Strict parse of an n8n `type: json` value. n8n stores json parameters as
 * STRINGS (and an expression `={{ JSON.stringify(x) }}` yields one), so a string
 * is parsed; invalid JSON throws a NodeOperationError naming the field — it is
 * never turned into a default or sent raw. An empty / whitespace string means
 * "not set" (UNSET). Non-strings pass through unchanged.
 */
function parseJsonField(raw: unknown, f: JsonField): unknown {
  if (typeof raw !== "string") return raw;
  if (raw.trim() === "") return UNSET;
  try {
    return JSON.parse(raw) as unknown;
  } catch (e) {
    throw new NodeOperationError(
      f.ctx.getNode(),
      `"${f.display}" (${f.name}) is not valid JSON (${e instanceof Error ? e.message : String(e)})`,
      { itemIndex: f.itemIndex },
    );
  }
}

function describeJson(v: unknown): string {
  if (v === null) return "null";
  if (Array.isArray(v)) return "an array";
  return typeof v === "object" ? "an object" : `a ${typeof v}`;
}

/** ⛔ Valid JSON of the wrong shape is an error naming the field — never a silent `{}` / `[]`. */
function shapeError(f: JsonField, want: string, got: unknown): NodeOperationError {
  return new NodeOperationError(
    f.ctx.getNode(),
    `"${f.display}" (${f.name}) must be ${want}, got ${describeJson(got)}`,
    { itemIndex: f.itemIndex },
  );
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  if (typeof v !== "object" || v === null || Array.isArray(v)) return false;
  const proto = Object.getPrototypeOf(v);
  return proto === Object.prototype || proto === null;
}

/**
 * Coerce an n8n `type: json` parameter to a plain object. n8n hands back an
 * object for a literal and a STRING when an expression produced JSON text
 * (`={{ JSON.stringify(x) }}` — the form every AA telemetry workflow uses), so
 * both are accepted. Not set (undefined / null / empty or whitespace string)
 * yields `{}`. INVALID JSON throws naming the field (parseJsonField), and so
 * does VALID JSON that is not a plain object (`[]`, `5`, `"x"`, `null` text).
 */
function asJsonObject(raw: unknown, f: JsonField): Record<string, unknown> {
  if (raw === undefined || raw === null) return {};
  const value = parseJsonField(raw, f);
  if (value === UNSET) return {};
  if (isPlainObject(value)) return value;
  throw shapeError(f, "a JSON object", value);
}

/**
 * Array counterpart of asJsonObject: UNSET when not set (undefined / null /
 * empty or whitespace string), the array otherwise; invalid JSON or valid
 * non-array JSON throws naming the field.
 */
function parseJsonArray(raw: unknown, f: JsonField): unknown[] | typeof UNSET {
  if (raw === undefined || raw === null) return UNSET;
  const value = parseJsonField(raw, f);
  if (value === UNSET) return UNSET;
  if (Array.isArray(value)) return value;
  throw shapeError(f, "a JSON array", value);
}

/** Same as asJsonObject but stringifies every value — Loki labels are strings. */
function asLabelMap(raw: unknown, f: JsonField): Record<string, string> {
  const obj = asJsonObject(raw, f);
  const out: Record<string, string> = {};
  for (const [k, v] of Object.entries(obj)) {
    if (v === undefined || v === null) continue;
    out[k] = typeof v === "string" ? v : JSON.stringify(v);
  }
  return out;
}

function normaliseLokiUrl(raw: unknown): string {
  const lokiUrl = String(raw ?? "").replace(/\/+$/, "");
  if (!lokiUrl) {
    throw new Error(
      "A Loki URL is required: set `lokiUrl` on the node, or Loki URL on the observabilityApi credential (e.g. http://localhost:3100).",
    );
  }
  return lokiUrl;
}

/**
 * Accept the fixedCollection shape, a bare array, or a JSON string of either.
 * Invalid JSON (in `entries` or in `entries.entryValues`) throws naming the
 * field; empty / whitespace means no entries.
 */
function normaliseEntries(raw: unknown, f: JsonField): Array<Record<string, unknown>> {
  if (raw === undefined || raw === null) return [];
  const value = parseJsonField(raw, f);
  if (value === UNSET) return [];
  if (Array.isArray(value)) return value as Array<Record<string, unknown>>;
  if (isPlainObject(value)) {
    const ev = parseJsonArray(value.entryValues, {
      ...f, display: `${f.display} › Entry Values`, name: `${f.name}.entryValues`,
    });
    return ev === UNSET ? [] : (ev as Array<Record<string, unknown>>);
  }
  throw shapeError(f, "a JSON array (or an object with entryValues)", value);
}

/**
 * Build and POST a single Loki stream. Shared by pushLogs + pushAAEventLog.
 *
 * Loki requires entries within a stream to be ordered by timestamp, and stores
 * nanosecond epoch strings. Each entry becomes one JSON log line.
 */
async function pushLokiStream(
  ctx: IExecuteFunctions,
  lokiUrl: string,
  labels: Record<string, string>,
  entries: Array<Record<string, unknown>>,
  itemIndex: number,
): Promise<IDataObject> {
  const values: Array<[string, string]> = entries.map((entry) => {
    const { timestamp, message, additionalFields, ...rest } = entry as {
      timestamp?: unknown; message?: unknown; additionalFields?: unknown;
      [k: string]: unknown;
    };

    let timestampNs: string;
    if (typeof timestamp === "number" && Number.isFinite(timestamp)) {
      // < 1e12 is seconds-ish/ms-ish heuristic kept from the original impl.
      timestampNs = timestamp < 1e12
        ? String(Math.round(timestamp * 1e9))
        : String(Math.round(timestamp * 1e6));
    } else if (typeof timestamp === "string" && timestamp !== "") {
      const parsed = new Date(timestamp).getTime();
      timestampNs = String((Number.isNaN(parsed) ? Date.now() : parsed) * 1e6);
    } else {
      timestampNs = String(Date.now() * 1e6);
    }

    const logData: IDataObject = {
      level: (entry.level as string) || "info",
      msg: message ?? "",
      ...rest,
      ...asJsonObject(additionalFields, { ctx, itemIndex, display: "Log Entries › Additional Fields", name: "additionalFields" }),
      ts: new Date(Number(timestampNs) / 1e6).toISOString(),
    };

    return [timestampNs, JSON.stringify(logData)];
  });

  values.sort((a, b) => (BigInt(a[0]) < BigInt(b[0]) ? -1 : BigInt(a[0]) > BigInt(b[0]) ? 1 : 0));

  const uri = `${lokiUrl}/loki/api/v1/push`;
  const response = (await ctx.helpers.request({
    method: "POST",
    uri,
    headers: { "Content-Type": "application/json" },
    body: { streams: [{ stream: labels, values }] },
    json: true,
    resolveWithFullResponse: true,
  })) as { statusCode?: number };

  return {
    success: true,
    endpoint: uri,
    entriesCount: values.length,
    labels,
    statusCode: response?.statusCode ?? 204,
    timestamp: new Date().toISOString(),
  };
}

